 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(10) if all(row[c] == grid[0][c] for row in grid) and all(grid[r][c] == grid[r][0] for r in range(h))) if False else None
    # The divider color appears as complete horizontal and vertical lines.
    sep_color = next(
        color for color in set(v for row in grid for v in row)
        if any(all(v == color for v in row) for row in grid)
        and any(all(grid[r][c] == color for r in range(h)) for c in range(w))
    )
    sep_rows = [r for r, row in enumerate(grid) if all(v == sep_color for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    row_spans = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_spans = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]
    ph, pw = row_spans[0][1] - row_spans[0][0], col_spans[0][1] - col_spans[0][0]

    # The first panel in each horizontal band carries that band's output color.
    band_colors = []
    for r0, r1 in row_spans:
        vals = {grid[r][c] for r in range(r0, r1) for c in range(*col_spans[0]) if grid[r][c] not in (0, sep_color)}
        band_colors.append(next(iter(vals)))

    # A nonempty panel outside the color-key column contains the pattern to replicate.
    pattern = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans[1:]:
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep_color)]
            if cells:
                pattern = cells
                break
        if pattern is not None:
            break
    if pattern is None:
        raise ValueError('No pattern panel found')

    out = [row[:] for row in grid]
    for bi, (r0, r1) in enumerate(row_spans):
        color = band_colors[bi]
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in pattern:
                out[r0 + dr][c0 + dc] = color
    return out
